const response   = $input.first().json;
const topicData  = $('Code: Pick Today\'s Topic').first().json;

// Extract text from Claude
let raw = '';
try { raw = response.content[0].text; }
catch(e) { console.log('Claude error:', JSON.stringify(response).slice(0,300)); }

// Parse JSON
let blog = null;
try {
  let cleaned = raw.trim();
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```[a-z]*\s*/,'').replace(/\s*```$/,'').trim();
  }
  blog = JSON.parse(cleaned);
} catch(e) {
  console.log('JSON parse failed, using fallback. Raw:', raw.slice(0,200));
}

// Validate / fallback
if (!blog || !blog.title || !blog.html_body) {
  const t = topicData.topic;
  blog = {
    title:            t.focus.slice(0,60),
    subtitle:         'Serving Plainview NY and all of Nassau County Long Island',
    meta_title:       t.focus.slice(0,60),
    meta_description: 'Visit Long Island Convenience at 605 Old Country Road Plainview NY for ' + t.focus.toLowerCase().slice(0,70) + '. Call +1 (917) 338-7086.',
    meta_keywords:    t.keywords.join(', '),
    tags:             ['Long Island','Plainview NY','Nassau County', t.category],
    html_body:        '<h2>' + t.focus + '</h2><p>Shop at Long Island Convenience, 605 Old Country Road, Plainview NY 11803. Serving Nassau County. Call +1 (917) 338-7086.</p>',
  };
  console.log('Using fallback content.');
}

// Ensure tags array
if (!Array.isArray(blog.tags)) {
  blog.tags = typeof blog.tags === 'string' ? blog.tags.split(',').map(t=>t.trim()) : ['Long Island','Plainview NY','Nassau County'];
}

// Prepend header image
const img = topicData.headerImg;
const alt = topicData.topic.focus + ' — Long Island Convenience Plainview NY Nassau County';
blog.html_body = '<p><img src="' + img + '" alt="' + alt + '" style="max-width:100%;border-radius:8px;margin:16px 0;"/></p>' + blog.html_body;

return [{ json: { blog, topic: topicData.topic, dateStr: topicData.dateStr, blogName: topicData.blogName } }];

const authResp = $('HTTP: Odoo Authenticate').first().json;
const blogData = $('Code: Parse Claude Response').first().json;

// ── Extract uid ──
const uid = authResp?.body?.result?.uid;

// ── Extract session_id from Set-Cookie header ──
// n8n may return set-cookie as string or array
let rawCookie = authResp?.headers?.['set-cookie'] || '';
if (Array.isArray(rawCookie)) rawCookie = rawCookie.join('; ');

let sessionId = '';
for (const part of rawCookie.split(';')) {
  const p = part.trim();
  if (p.toLowerCase().startsWith('session_id=')) {
    sessionId = p.split('=', 2)[1];
    break;
  }
}

if (!uid || !sessionId) {
  const dump = JSON.stringify(authResp).slice(0, 500);
  throw new Error('Odoo auth failed. uid=' + uid + ' session=' + (sessionId||'EMPTY') + ' | Response: ' + dump);
}

console.log('Odoo auth OK. uid=' + uid + ' session=' + sessionId.slice(0,12) + '...');

const b = blogData.blog;
const topic = blogData.topic;

const title     = (b.title || topic.focus).slice(0, 255);
const subtitle  = (b.subtitle || '').slice(0, 255);
const metaTitle = (b.meta_title || title).slice(0, 255);
const metaDesc  = (b.meta_description || '').slice(0, 400);
const metaKw    = (b.meta_keywords || topic.keywords.join(', ')).slice(0, 255);

return [{ json: {
  sessionId,
  uid,
  createPayload: {
    jsonrpc: '2.0',
    method:  'call',
    id:      2,
    params: {
      model:  'blog.post',
      method: 'create',
      args: [{
        name:                     title,
        subtitle:                 subtitle,
        content:                  b.html_body,
        blog_id:                  topic.blog_id,
        website_id:               1,
        website_published:        true,
        is_published:             true,
        website_meta_title:       metaTitle,
        website_meta_description: metaDesc,
        website_meta_keywords:    metaKw,
      }],
      kwargs: {}
    }
  },
  blogTitle:    title,
  blogCategory: topic.category,
  blogBlogId:   topic.blog_id,
  blogName:     blogData.blogName,
} }];

const createResp = $('HTTP: Odoo Create Blog Post').first().json;
const readResp   = $('HTTP: Odoo Read Post URL').first().json;
const buildData  = $('Code: Extract Session + Build Payload').first().json;
const blogData   = $('Code: Parse Claude Response').first().json;

const postId = createResp?.result;
if (!postId || typeof postId !== 'number') {
  throw new Error('Post creation failed: ' + JSON.stringify(createResp).slice(0,400));
}

const postRecord = readResp?.result?.[0] || {};
let liveUrl = postRecord.website_absolute_url || '';

if (!liveUrl) {
  const slugMap = {1:'our-blog-1',2:'sports-trading-cards-2',3:'balloons-party-decor-3',4:'print-mail-services-4',5:'gift-baskets-gifts-5',7:'convenience-grocery-7'};
  const blogSlug = slugMap[buildData.blogBlogId] || 'our-blog-1';
  const titleSlug = (buildData.blogTitle||'').toLowerCase().replace(/[^a-z0-9\s-]/g,'').replace(/\s+/g,'-').replace(/-+/g,'-').slice(0,80);
  liveUrl = 'https://www.longislandconvenience.com/blog/' + blogSlug + '/' + titleSlug + '-' + postId;
}

const gscUrl = 'https://search.google.com/search-console/inspect?resource_id=https%3A%2F%2Fwww.longislandconvenience.com%2F&id=' + encodeURIComponent(liveUrl);

console.log('═══════════════════════════════════════════════════');
console.log('✅ DAILY BLOG PUBLISHED');
console.log('   Blog section : ' + buildData.blogName);
console.log('   Category     : ' + buildData.blogCategory);
console.log('   Post ID      : ' + postId);
console.log('   Title        : ' + buildData.blogTitle);
console.log('   Live URL     : ' + liveUrl);
console.log('   GSC Inspect  : ' + gscUrl);
console.log('   Published    : ' + (postRecord.is_published || true));
console.log('═══════════════════════════════════════════════════');

return [{ json: {
  success:        true,
  postId,
  blogSection:    buildData.blogName,
  blogCategory:   buildData.blogCategory,
  blogTitle:      buildData.blogTitle,
  liveUrl,
  gscInspectUrl:  gscUrl,
  gscDashboard:   'https://search.google.com/search-console/',
  blogIndex:      'https://www.longislandconvenience.com/blog',
  publishedAt:    new Date().toISOString(),
  metaDescription: blogData.blog.meta_description || '',
} }];
